def run(_context):
    import adsk.core, adsk.fusion, adsk.cam, json
    app = adsk.core.Application.get()
    doc = app.activeDocument
    cam = adsk.cam.CAM.cast(doc.products.itemByProductType('CAMProductType'))
    s = cam.setups[0]
    print(mb.wcs_state() if hasattr(mb,'wcs_state') else '')
    for p in s.parameters:
        try:
            v = p.expression
        except Exception:
            v = None
        if any(k in p.name.lower() for k in ['stock','wcs','origin','model','job','operation_type','fixture']):
            print(p.name, "=", v)

